// 📅 Obtener fecha de hoy sin hora para comparar solo por día
function obtenerHoy() {
  const hoy = new Date();
  hoy.setHours(0, 0, 0, 0);
  return hoy;
}

// 📅 Parsear fecha en formato YYYY-MM-DD
function parsearFecha(fechaStr) {
  if (!fechaStr) return null;
  const partes = fechaStr.split("-");
  if (partes.length === 3) {
    return new Date(parseInt(partes[0]), parseInt(partes[1]) - 1, parseInt(partes[2]));
  }
  return null;
}

// 🔹 Obtener todos los turnos del nodo Get_Turnos
const turnosRaw = $("Get_Turnos").all();
const hoy = obtenerHoy();

// 🔍 Filtrar solo turnos con fecha MAYOR a hoy
const turnosFuturos = turnosRaw.filter(item => {
  const turno = item.json || item;
  const fecha = parsearFecha(turno.Fecha);
  return fecha !== null && fecha > hoy;
});

// ⚠️ Si no hay turnos futuros, devolver respuesta vacía
if (turnosFuturos.length === 0) {
  return [
    {
      json: {
        response: "no_tiene_turno",
        tieneTurno: false,
        turno: null,
        mensaje: "No hay turnos vigentes para esta patente"
      }
    }
  ];
}

// 📋 Ordenar por fecha ascendente y tomar el más próximo
turnosFuturos.sort((a, b) => {
  const fechaA = parsearFecha((a.json || a).Fecha);
  const fechaB = parsearFecha((b.json || b).Fecha);
  return fechaA - fechaB;
});

const turnoVigente = turnosFuturos[0].json || turnosFuturos[0];

// ✅ Devolver el turno más próximo vigente
return [
  {
    json: {
      response: "tiene_turno",
      tieneTurno: true,
      turno: {
        Fecha: turnoVigente.Fecha,
        Hora: turnoVigente.Hora,
        Tiempo: turnoVigente.Tiempo,
        Servicio: turnoVigente.Servicio,
        Patente: turnoVigente.Patente,
        Taller: turnoVigente.Taller,
        ID_Calendario: turnoVigente.ID_Calendario,
        ID_Turno: turnoVigente.ID_Turno
      }
    }
  }
];
